import{_ as i,c as s,o as a,j as o,Y as r,t as n}from"./chunks/framework.BNTND4LZ.js";const k=JSON.parse('{"title":"git-init | x-cmd man (git man1) | Create an empty Git repository or reinitialize an existing","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-init - Create an empty Git repository or reinitialize an existing","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-init | x-cmd man (git man1) | Create an empty Git repository or reinitialize an existing"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-init - Create an empty Git repository or reinitialize an existing"}]]},"headers":[],"params":{"isMan":true,"man":"git-init","category":"git man1","desc":"Create an empty Git repository or reinitialize an existing"},"relativePath":"git/man1/git-init.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-init.md"},p={class:"visually-hidden"};function h(t,e,g,d,c,m){return a(),s("div",null,[o("h1",p,n(t.$params.man),1),e[0]||(e[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-init - Create an empty Git repository or reinitialize an existing one</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-q </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --quiet]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--bare] [--template</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template-directory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [--separate-git-dir </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git-dir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [--object-format</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">format</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [-b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">branch-name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --initial-branch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">branch-name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [--shared[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">permissions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">directory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This command creates an empty Git repository - basically a <strong>.git</strong> directory with subdirectories for <strong>objects</strong>, <strong>refs/heads</strong>, <strong>refs/tags</strong>, and template files. An initial branch without any commits will be created (see the <strong>--initial-branch</strong> option below for its name).</p><p>If the <strong>$GIT_DIR</strong> environment variable is set then it specifies a path to use instead of <strong>./.git</strong> for the base of the repository.</p><p>If the object storage directory is specified via the <strong>$GIT_OBJECT_DIRECTORY</strong> environment variable then the sha1 directories are created underneath - otherwise the default <strong>$GIT_DIR/objects</strong> directory is used.</p><p>Running <em>git init</em> in an existing repository is safe. It will not overwrite things that are already there. The primary reason for rerunning <em>git init</em> is to pick up newly added templates (or to move the repository to another place if --separate-git-dir is given).</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-q, --quiet</p><blockquote><p>Only print error and warning messages; all other output will be suppressed.</p></blockquote><p>--bare</p><blockquote><p>Create a bare repository. If <strong>GIT_DIR</strong> environment is not set, it is set to the current working directory.</p></blockquote><p>--object-format=&lt;format&gt;</p><blockquote><p>Specify the given object format (hash algorithm) for the repository. The valid values are <em>sha1</em> and (if enabled) <em>sha256</em>. <em>sha1</em> is the default.</p><p>THIS OPTION IS EXPERIMENTAL! SHA-256 support is experimental and still in an early stage. A SHA-256 repository will in general not be able to share work with &quot;regular&quot; SHA-1 repositories. It should be assumed that, e.g., Git internal file formats in relation to SHA-256 repositories may change in backwards-incompatible ways. Only use <strong>--object-format=sha256</strong> for testing purposes.</p></blockquote><p>--template=&lt;template-directory&gt;</p><blockquote><p>Specify the directory from which templates will be used. (See the &quot;TEMPLATE DIRECTORY&quot; section below.)</p></blockquote><p>--separate-git-dir=&lt;git-dir&gt;</p><blockquote><p>Instead of initializing the repository as a directory to either <strong>$GIT_DIR</strong> or <strong>./.git/</strong>, create a text file there containing the path to the actual repository. This file acts as filesystem-agnostic Git symbolic link to the repository.</p><p>If this is reinitialization, the repository will be moved to the specified path.</p></blockquote><p>-b &lt;branch-name&gt;, --initial-branch=&lt;branch-name&gt;</p><blockquote><p>Use the specified name for the initial branch in the newly created repository. If not specified, fall back to the default name (currently <strong>master</strong>, but this is subject to change in the future; the name can be customized via the <strong>init.defaultBranch</strong> configuration variable).</p></blockquote><p>--shared[=(false|true|umask|group|all|world|everybody|&lt;perm&gt;)]</p><blockquote><p>Specify that the Git repository is to be shared amongst several users. This allows users belonging to the same group to push into that repository. When specified, the config variable &quot;core.sharedRepository&quot; is set so that files and directories under <strong>$GIT_DIR</strong> are created with the requested permissions. When not specified, Git will use permissions reported by umask(2).</p><p>The option can have the following values, defaulting to <em>group</em> if no value is given:</p><p><em>umask</em> (or <em>false</em>)</p><blockquote><p>Use permissions reported by umask(2). The default, when <strong>--shared</strong> is not specified.</p></blockquote><p><em>group</em> (or <em>true</em>)</p><blockquote><p>Make the repository group-writable, (and g+sx, since the git group may be not the primary group of all users). This is used to loosen the permissions of an otherwise safe umask(2) value. Note that the umask still applies to the other permission bits (e.g. if umask is <em>0022</em>, using <em>group</em> will not remove read privileges from other (non-group) users). See <em>0xxx</em> for how to exactly specify the repository permissions.</p></blockquote><p><em>all</em> (or <em>world</em> or <em>everybody</em>)</p><blockquote><p>Same as <em>group</em>, but make the repository readable by all users.</p></blockquote><p><em>&lt;perm&gt;</em></p><blockquote><p><em>&lt;perm&gt;</em> is a 3-digit octal number prefixed with <strong>0</strong> and each file will have mode <em>&lt;perm&gt;</em>. <em>&lt;perm&gt;</em> will override users&#39; umask(2) value (and not only loosen permissions as <em>group</em> and <em>all</em> does). <em>0640</em> will create a repository which is group-readable, but not group-writable or accessible to others. <em>0660</em> will create a repo that is readable and writable to the current user and group, but inaccessible to others (directories and executable files get their <strong>x</strong> bit from the <strong>r</strong> bit for corresponding classes of users).</p></blockquote></blockquote><p>By default, the configuration flag <strong>receive.denyNonFastForwards</strong> is enabled in shared repositories, so that you cannot force a non fast-forwarding push into it.</p><p>If you provide a <em>directory</em>, the command is run inside it. If this directory does not exist, it will be created.</p><h2 id="template-directory" tabindex="-1">TEMPLATE DIRECTORY <a class="header-anchor" href="#template-directory" aria-label="Permalink to &quot;TEMPLATE DIRECTORY&quot;">​</a></h2><p>Files and directories in the template directory whose name do not start with a dot will be copied to the <strong>$GIT_DIR</strong> after it is created.</p><p>The template directory will be one of the following (in order):</p><blockquote><p>·</p><p>the argument given with the <strong>--template</strong> option;</p></blockquote><blockquote><p>·</p><p>the contents of the <strong>$GIT_TEMPLATE_DIR</strong> environment variable;</p></blockquote><blockquote><p>·</p><p>the <strong>init.templateDir</strong> configuration variable; or</p></blockquote><blockquote><p>·</p><p>the default template directory: <strong>/usr/share/git-core/templates</strong>.</p></blockquote><p>The default template directory includes some directory structure, suggested &quot;exclude patterns&quot; (see <strong>gitignore</strong>(5)), and sample hook files.</p><p>The sample hooks are all disabled by default. To enable one of the sample hooks rename it by removing its <strong>.sample</strong> suffix.</p><p>See <strong>githooks</strong>(5) for more general info on hook execution.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Start a new Git repository for an existing code base</p><blockquote><blockquote><pre><code>$ cd /path/to/my/codebase
$ git init      (1)
$ git add .     (2)
$ git commit    (3)
</code></pre></blockquote><hr><pre><code>**1.** Create a /path/to/my/codebase/.git directory.
**2.** Add all existing files to the index.
**3.** Record the pristine state as the first commit in the history.
</code></pre><hr></blockquote><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>Everything below this line in this section is selectively included from the <strong>git-config</strong>(1) documentation. The content is the same as what&#39;s found there:</p><p>init.templateDir</p><blockquote><p>Specify the directory from which templates will be copied. (See the &quot;TEMPLATE DIRECTORY&quot; section of <strong>git-init</strong>(1).)</p></blockquote><p>init.defaultBranch</p><blockquote><p>Allows overriding the default branch name e.g. when initializing a new repository.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,47))])}const b=i(l,[["render",h]]);export{k as __pageData,b as default};
